const TEAMS=[
 {id:'mumbai',name:'Mumbai Mariners',short:'MUM',crest:'🌊',color:'#48c6bd',city:'Mumbai',tag:'West coast legends'},
 {id:'chennai',name:'Chennai Chargers',short:'CHE',crest:'⚡',color:'#f4c84d',city:'Chennai',tag:'Never stop charging'},
 {id:'bengaluru',name:'Bengaluru Blazers',short:'BLR',crest:'🔥',color:'#f07469',city:'Bengaluru',tag:'Play bold, play free'},
 {id:'delhi',name:'Delhi Dynamos',short:'DEL',crest:'🦅',color:'#a995f2',city:'Delhi',tag:'Capital of cricket'}
];
const FIRST=['Aarav','Ishaan','Kabir','Vihaan','Arjun','Rohan','Dev','Neel','Reyansh','Kunal','Aditya','Yash','Pranav','Krish','Samar','Shaurya','Ayaan','Ritvik','Manav','Dhruv','Akhil','Tanish','Nikhil','Varun','Harsh','Siddharth','Rahul','Aniket','Sameer','Omkar','Jay','Keshav','Rishi','Vikram','Amit','Abhinav','Rajat','Tejas','Gautam','Shivam'];
const LAST=['Sharma','Patel','Iyer','Reddy','Desai','Nair','Singh','Kulkarni','Menon','Verma','Khan','Joshi','Mehta','Rao','Kapoor','Pillai','Jadhav','Chopra','Bose','Mishra','Gill','Shetty','Thakur','Yadav','Chawla','Dube','Naidu','Saxena','Ghosh','Bhat'];
const ROLES=['Batter','Bowler','All-rounder','Wicketkeeper'];
const makePlayers=()=>Array.from({length:100},(_,i)=>{let role=ROLES[(i*7+Math.floor(i/4))%4],seed=(i*17+13)%27;let bat=role==='Bowler'?54+seed:67+seed,bowl=role==='Batter'?45+seed:61+seed,field=59+(i*11)%36,overall=Math.round((bat+bowl+field)/3);return{id:i+1,name:`${FIRST[(i*13+3)%FIRST.length]} ${LAST[(i*11+5)%LAST.length]}`,role,bat,bowl,field,overall,base:Math.max(3,Math.round((overall-49)/6)),country:i%13===0?'Overseas':'India',hand:i%3===0?'Left hand':'Right hand'}});
const PLAYERS=makePlayers();
const FEATURED=[PLAYERS[2],PLAYERS[13],PLAYERS[21],PLAYERS[36],PLAYERS[42],PLAYERS[54],PLAYERS[61],PLAYERS[68],PLAYERS[77],PLAYERS[83],PLAYERS[90],PLAYERS[97]].map((p,i)=>({...p,name:['Ishaan Sharma','Aarav Gill','Kabir Nair','Reyansh Patel','Dev Kulkarni','Ayaan Reddy','Vihaan Iyer','Arjun Menon','Rohan Singh','Shaurya Joshi','Neel Kapoor','Pranav Desai'][i],overall:[94,91,89,87,86,84,82,80,79,77,75,73][i],bat:[96,94,83,88,79,85,91,78,83,82,76,80][i],bowl:[57,61,91,74,89,81,69,87,72,76,82,68][i],base:[18,17,15,14,13,12,11,10,9,8,7,6][i]}));
const freshState=()=>({screen:'select',userId:null,budget:100,rosters:Object.fromEntries(TEAMS.map(t=>[t.id,[]])),auctionIndex:0,currentBid:0,highBidder:null,bidTimer:0,leagueStarted:false,fixture:0,innings:1,runs:0,wickets:0,balls:0,target:null,oppRuns:0,oppWickets:0,oppBalls:0,points:Object.fromEntries(TEAMS.map(t=>[t.id,0])),results:[],tactic:'Balanced',message:'The lights are on. Time to make history.',lastBall:null,matchDone:false,turnCount:0});
let state=freshState(),scene3d=null,tab='squad',toastTimer;
const $=s=>document.querySelector(s),screen=$('#screen');
function team(id){return TEAMS.find(t=>t.id===id)}function money(v){return `${v} Cr`}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showToast(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function selectScreen(){state.screen='select';render();}
function render(){if(state.screen==='select'){screen.innerHTML=`<section class="hero"><div class="eyebrow">A new season starts here</div><h1 class="heading">Your city. Your call.<br><span style="color:var(--lime)">Your trophy.</span></h1><p class="subhead">Take the chair as franchise manager. Build a side at the auction, then lead them through a fast, hands-on T20 showdown.</p></section><div class="team-grid">${TEAMS.map(t=>`<button class="team-card" style="--team:${t.color}" onclick="chooseTeam('${t.id}')"><div class="crest">${t.crest}</div><h3>${t.name}</h3><p>${t.tag}</p><div class="founded">${t.city.toUpperCase()} &nbsp;·&nbsp; FRANCHISE</div></button>`).join('')}</div><div class="setup-tip"><span style="color:var(--lime);font-size:17px">✦</span><span>Choose your franchise to begin. <b>₹100 Cr</b> purse · 12 quick auction lots · 4 teams.</span></div>`;return}
if(state.screen==='auction'){renderAuction();return}if(state.screen==='match'){renderMatch();return}if(state.screen==='result'){renderResult();return}}
window.chooseTeam=id=>{state=freshState();state.userId=id;state.screen='auction';state.auctionIndex=0;auctionLot();renderAuction()};
function auctionLot(){if(state.auctionIndex>=FEATURED.length){finishAuction();return}let p=FEATURED[state.auctionIndex];state.currentBid=p.base;state.highBidder=null;state.bidTimer=0;state.turnCount=0;state.message=`Lot ${state.auctionIndex+1} is live. Make your move.`;}
function aiAuctionStep(){if(state.screen!=='auction'||state.highBidder==='done')return;let p=FEATURED[state.auctionIndex],available=TEAMS.filter(t=>t.id!==state.userId&&state.rosters[t.id].length<4&&state.budget>0);if(state.highBidder===state.userId){let challengers=available.filter(t=>state.rosters[t.id].length<4&&state.budget>=state.currentBid+2&&Math.random()<Math.max(.15,(p.overall-60)/65));if(challengers.length){let bidder=challengers[Math.floor(Math.random()*challengers.length)];state.highBidder=bidder.id;state.currentBid+=2;state.message=`${bidder.name} raises by ₹2 Cr. Do you want to counter?`;renderAuction();return} }
else {let bidder=available.filter(t=>state.budget>=state.currentBid+2&&Math.random()<(p.overall>85?.62:.35)).sort(()=>Math.random()-.5)[0];if(bidder){state.highBidder=bidder.id;state.currentBid+=2;state.message=`${bidder.name} enters the bidding at ${money(state.currentBid)}.`;renderAuction();return}}
state.bidTimer++;if(state.bidTimer>=2||state.turnCount>=5){closeLot();return}state.turnCount++;setTimeout(aiAuctionStep,1000);}
window.placeBid=()=>{let p=FEATURED[state.auctionIndex],next=state.currentBid+(state.highBidder?2:0);if(state.rosters[state.userId].length>=4){showToast('Your squad is full — let this lot go.');return}if(state.budget<next){showToast('Not enough purse left for that bid.');return}if(state.highBidder===state.userId){showToast('You already hold the bid. Wait for the hammer.');return}state.currentBid=next;state.highBidder=state.userId;state.bidTimer=0;state.turnCount=0;state.message=`You're leading at ${money(state.currentBid)}!`;renderAuction();setTimeout(aiAuctionStep,700)};
window.passLot=()=>{if(state.highBidder===state.userId){closeLot();return}state.message='You pass on this player. The other franchises are bidding…';state.bidTimer=1;state.turnCount=0;renderAuction();setTimeout(aiAuctionStep,350)};
function closeLot(){let p=FEATURED[state.auctionIndex];if(state.highBidder===state.userId){state.budget-=state.currentBid;state.rosters[state.userId].push({...p,price:state.currentBid});state.message=`SOLD to ${team(state.userId).name} for ${money(state.currentBid)}!`;}else if(state.highBidder){state.rosters[state.highBidder].push({...p,price:state.currentBid});state.message=`SOLD to ${team(state.highBidder).name} for ${money(state.currentBid)}.`;}else state.message='Unsold — the room passes.';state.highBidder='done';renderAuction();setTimeout(()=>{state.auctionIndex++;if(state.auctionIndex>=FEATURED.length){finishAuction()}else{auctionLot();renderAuction()}},950)}
function finishAuction(){for(let i=0;i<TEAMS.length;i++){let t=TEAMS[i];while(state.rosters[t.id].length<4){let p=PLAYERS[(i*21+state.rosters[t.id].length*9+state.auctionIndex)%PLAYERS.length];let price=Math.min(p.base,Math.max(1,state.budget));if(t.id===state.userId&&state.budget<1)break;state.rosters[t.id].push({...p,price});if(t.id===state.userId)state.budget-=price;}}
state.screen='lobby';state.message='Your squad is locked. The league awaits.';renderLobby();}
function squadRoster(id){return state.rosters[id]||[]}
function renderAuction(){if(state.screen!=='auction')return;let p=FEATURED[state.auctionIndex],me=team(state.userId),current=state.highBidder==='done'?null:state.highBidder;screen.innerHTML=`<div class="auction-top"><div><div class="eyebrow">The player auction</div><h1 class="heading">Build your <span style="color:var(--lime)">dream XI.</span></h1><p class="subhead">A quick-fire auction. 12 marquee lots, four franchises, one winning squad.</p></div><div class="stage-label"><i class="live-dot"></i> LIVE AUCTION</div></div><div class="app-shell" style="margin-top:24px"><div class="left-column"><section class="panel"><div class="player-feature"><div><div class="player-number">MARQUEE LOT ${String(state.auctionIndex+1).padStart(2,'0')} <span style="color:#839b91">/ 12</span></div><h2 class="player-name">${p.name}</h2><div class="player-sub">${p.country} &nbsp;·&nbsp; ${p.hand} &nbsp;·&nbsp; ${p.role}</div><span class="role-pill">${p.role.toUpperCase()}</span><div class="stats-row"><div class="stat-chip">BAT <b>${p.bat}</b></div><div class="stat-chip">BOWL <b>${p.bowl}</b></div><div class="stat-chip">FIELD <b>${p.field}</b></div><div class="stat-chip">BASE <b>${money(p.base)}</b></div></div></div><div class="player-art"><div class="aura"></div><div class="jersey"></div><div class="rating"><strong>${p.overall}</strong><span>RATING</span></div></div></div><div class="team-strip">${TEAMS.map(t=>`<div class="team-bid ${current===t.id?'active':''}"><div class="tb-name">${t.crest} ${t.id===state.userId?'YOU':t.short}</div><strong>${current===t.id?money(state.currentBid):'—'}</strong></div>`).join('')}</div><div class="progress-wrap"><div class="progress-label"><span>AUCTION PROGRESS</span><span>${state.auctionIndex} of 12 lots closed</span></div><div class="progress"><i style="width:${state.auctionIndex/12*100}%"></i></div></div><div class="auction-footer"><div class="bid-current">${current?`${team(current).name} leads`:'Opening bid'}<strong>${money(state.currentBid)}</strong></div><div class="auction-actions"><button class="btn secondary" onclick="passLot()">${current===state.userId?'Let it go':'Pass'}</button><button class="btn" onclick="placeBid()" ${state.highBidder==='done'?'disabled':''}>${current===state.userId?'Leading ✓':`Bid ${money(state.currentBid+(current?2:0))} ↗`}</button></div></div></section><div class="notice">💡 &nbsp;One tap to bid. Rivals counter automatically. Your purse and squad needs are always in view.</div></div><aside class="right-column"><section class="panel"><div class="panel-head"><h3 class="panel-title">${me.crest} ${me.name}</h3><span class="tag">YOUR FRANCHISE</span></div><div class="side-budget"><div class="mini-label">REMAINING PURSE</div><div class="budget-big">${money(state.budget)} <span>/ ₹100 Cr</span></div><div class="budget-bar"><i style="width:${state.budget}%"></i></div><div class="budget-foot"><span>Squad ${squadRoster(state.userId).length} / 4</span><span>${100-state.budget} Cr spent</span></div></div><div class="panel-head"><h3 class="panel-title">Your squad</h3><span class="mini-label">${squadRoster(state.userId).length} PLAYERS</span></div><div class="roster">${squadRoster(state.userId).length?squadRoster(state.userId).map(rosterHTML).join(''):'<div class="empty-roster">Your first signing is just a bid away.</div>'}</div></section><section class="panel"><div class="panel-head"><h3 class="panel-title">Rival purses</h3><span class="mini-label">4 FRANCHISES</span></div><div class="standings">${TEAMS.filter(t=>t.id!==state.userId).map(t=>`<div class="standing-row"><span>${t.crest}</span><span>${t.name}</span><span class="mini-label" style="text-align:right">${squadRoster(t.id).length} / 4</span><strong>${100-state.rosters[t.id].reduce((a,p)=>a+p.price,0)} Cr</strong></div>`).join('')}</div></section></aside></div>`}
function rosterHTML(p){return `<div class="roster-row"><div class="avatar">${p.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div class="roster-info"><strong>${p.name}</strong><small>${p.role} · OVR ${p.overall}</small></div><div class="roster-val">${p.price} Cr</div></div>`}
function renderLobby(){state.screen='lobby';let me=team(state.userId);screen.innerHTML=`<section class="hero"><div class="eyebrow">Auction complete · season 2026</div><h1 class="heading">The ${me.name} are <span style="color:var(--lime)">ready.</span></h1><p class="subhead">Your four-player match squad is assembled. Set your match plan and chase the first points on the board.</p></section><div class="app-shell" style="margin-top:24px"><div class="left-column"><section class="panel"><div class="panel-head"><h3 class="panel-title">Your match squad</h3><span class="tag">${squadRoster(state.userId).length} PLAYERS · ${state.budget} CR LEFT</span></div><div class="roster">${squadRoster(state.userId).map(rosterHTML).join('')}</div><div class="notice">A compact exhibition format keeps every match quick: 2 overs per side, one match against each rival.</div></section><section class="panel"><div class="panel-head"><h3 class="panel-title">Opening fixture</h3><span class="stage-label">MATCH 01</span></div><div style="padding:26px 22px;display:flex;align-items:center;justify-content:space-around;text-align:center;gap:8px"><div><div style="font-size:35px">${me.crest}</div><strong style="font:600 16px 'Space Grotesk'">${me.short}</strong><div class="mini-label" style="margin-top:5px">YOU BAT FIRST</div></div><div style="color:var(--muted);font:700 13px 'Space Grotesk'">VS</div><div><div style="font-size:35px">${team(opponent(0)).crest}</div><strong style="font:600 16px 'Space Grotesk'">${team(opponent(0)).short}</strong><div class="mini-label" style="margin-top:5px">AWAY · 2 OVERS</div></div></div><div style="padding:0 20px 20px"><button class="btn" style="width:100%" onclick="startMatch()">Take the field&nbsp; ↗</button></div></section></div><aside class="right-column"><section class="panel"><div class="panel-head"><h3 class="panel-title">League table</h3><span class="mini-label">P · PTS</span></div>${standingsHTML()}</section><section class="panel"><div class="panel-head"><h3 class="panel-title">Competition format</h3></div><div class="notice" style="border:0;padding:16px 19px">🏏 &nbsp;Three fast fixtures<br>⏱ &nbsp;2 overs per innings<br>🎯 &nbsp;Tap to play each ball<br>🏆 &nbsp;Top points take the title</div></section></aside></div>`;}
function opponent(n){let others=TEAMS.filter(t=>t.id!==state.userId);return others[n%others.length].id}function standingsHTML(){return `<div class="standings">${TEAMS.map((t,i)=>`<div class="standing-row"><span class="pos">${i+1}</span><span class="${t.id===state.userId?'ours':''}">${t.crest} ${t.name}</span><span class="muted" style="text-align:right">${state.results.filter(r=>r.id===t.id).length} P</span><strong>${state.points[t.id]} pts</strong></div>`).join('')}</div>`}
window.startMatch=()=>{state.screen='match';state.innings=1;state.runs=0;state.wickets=0;state.balls=0;state.target=null;state.oppRuns=0;state.oppWickets=0;state.oppBalls=0;state.matchDone=false;state.lastBall=null;state.message='First ball coming up. Pick your approach.';renderMatch();setTimeout(initScene,100)};
function scoreOver(balls){return `${Math.floor(balls/6)}.${balls%6}`}function renderMatch(){if(state.screen!=='match')return;let me=team(state.userId),opp=team(opponent(state.fixture)),first=state.innings===1,score=first?state.runs:state.oppRuns,wickets=first?state.wickets:state.oppWickets,balls=first?state.balls:state.oppBalls;let chase=state.target!==null;screen.innerHTML=`<div class="league-head"><div><div class="eyebrow">Match ${state.fixture+1} of 3 · ${me.name} vs ${opp.name}</div><h1 class="heading" style="margin-bottom:5px">${first?'Set the target.':'Bring it home.'}</h1></div><span class="stage-label"><i class="live-dot"></i> ${first?'1ST INNINGS':'2ND INNINGS'}</span></div><div class="app-shell" style="margin-top:20px"><div class="left-column"><section class="panel"><div class="pitch-wrap"><canvas id="pitch"></canvas><div class="score-overlay"><div class="score-card"><div class="score-label">${first?me.short:opp.short} ${chase?'· CHASING':'· INNINGS'}</div><div class="score-num">${score}<span> / ${wickets}</span></div></div><div class="score-card" style="text-align:right"><div class="score-label">OVERS</div><div class="score-num">${scoreOver(balls)}<span> / 2</span></div></div></div></div><div class="pitch-foot">3D STADIUM VIEW · BOUNDARY LEAGUE</div><div class="match-controls"><div class="match-meta"><span>${chase?`TARGET ${state.target} · ${Math.max(0,state.target-score)} TO WIN`:'6 balls per over · 2 overs total'}</span><span>${state.matchDone?'INNINGS COMPLETE':`${12-balls} BALLS LEFT`}</span></div><div class="tactic-row">${['Defensive','Balanced','Aggressive'].map(x=>`<button class="tactic ${state.tactic===x?'selected':''}" onclick="setTactic('${x}')">${x==='Defensive'?'🛡️':x==='Aggressive'?'⚡':'◉'} &nbsp;${x}</button>`).join('')}</div><div class="play-row"><button class="btn" onclick="playBall()" ${state.matchDone?'disabled':''}>${first?'Play next ball':'Bowl next ball'} &nbsp;↗</button><button class="btn secondary" onclick="quickOver()" ${state.matchDone?'disabled':''}>Sim over</button></div></div></section><section class="panel"><div class="commentary" id="commentary">${state.lastBall||'🏟️ &nbsp;'}<strong>${state.lastBall?'':esc(state.message)}</strong></div></section></div><aside class="right-column"><section class="panel"><div class="panel-head"><h3 class="panel-title">On the field</h3><span class="tag">${me.short} XI</span></div><div class="roster-list">${squadRoster(state.userId).map((p,i)=>`<div class="roster-row" style="padding:11px 16px"><div class="avatar">${i===0?'★':p.name[0]}</div><div class="roster-info"><strong>${p.name}</strong><small>${p.role}</small></div><div class="roster-val">${p.overall}</div></div>`).join('')}</div><div class="notice">${first?'Your top batter is in. Keep an eye on the chase rate.':'Select a bowling plan, then deliver.'}</div></section><section class="panel"><div class="panel-head"><h3 class="panel-title">League table</h3><span class="mini-label">P · PTS</span></div>${standingsHTML()}</section><button class="btn ghost" style="justify-self:start" onclick="confirmLeave()">← &nbsp;Exit match</button></aside></div>`;drawSceneBall();}
window.setTactic=x=>{state.tactic=x;renderMatch()};
function powerAvg(id,kind){let list=squadRoster(id);if(!list.length)return 68;return list.reduce((s,p)=>s+(kind==='bat'?p.bat:p.bowl),0)/list.length}
function playBall(){if(state.matchDone)return;let isBatting=state.innings===1,battingTeam=isBatting?state.userId:opponent(state.fixture),bowlingTeam=isBatting?opponent(state.fixture):state.userId;let batter=squadRoster(battingTeam)[state.balls%Math.max(1,squadRoster(battingTeam).length)]||PLAYERS[4],bowler=squadRoster(bowlingTeam).filter(p=>p.role!=='Batter')[state.balls%Math.max(1,squadRoster(bowlingTeam).filter(p=>p.role!=='Batter').length)]||squadRoster(bowlingTeam)[0]||PLAYERS[1];let tactic=state.tactic;let batSkill=(batter?.bat||72)/100,bowlSkill=(bowler?.bowl||69)/100;let aggression=tactic==='Aggressive'?.19:tactic==='Defensive'?.- .11:0;let wicketChance=Math.max(.035,Math.min(.24,.105+(bowlSkill-batSkill)*.12+aggression*.25));let r=Math.random(),runs=0,out=false;if(r<wicketChance)out=true;else{let fourChance=.16+aggression*.24+(batSkill-.7)*.12,sixChance=.055+aggression*.12+(batSkill-.7)*.08;if(r< wicketChance+sixChance)runs=6;else if(r<wicketChance+sixChance+fourChance)runs=4;else{let probs=[.32,.2,.08,.08,.025];let z=Math.random(),cum=0;runs=0;for(let i=0;i<probs.length;i++){cum+=probs[i];if(z<cum){runs=i+1;break}}}}
if(isBatting){state.balls++;if(out)state.wickets++;else state.runs+=runs;}else{state.oppBalls++;if(out)state.oppWickets++;else state.oppRuns+=runs;}let outcome=out?'OUT!':runs===6?'SIX!':runs===4?'FOUR!':runs===0?'Dot ball.':`${runs} run${runs===1?'':'s'}.`;state.lastBall=`${out?'🧤':runs>=4?'💥':'🏏'} &nbsp;<strong>${outcome}</strong> ${batter?.name||'Batter'} ${out?'is caught out.':runs===6?'sends it into the stands.':runs===4?'finds the rope.':`takes ${runs} off the ball.`}`;state.message=outcome;
if(isBatting&&state.balls>=12){state.target=state.runs+1;state.innings=2;state.message=`Innings closed at ${state.runs}. Target: ${state.target}.`;state.lastBall=`🏏 &nbsp;<strong>Innings complete.</strong> ${state.runs}/${state.wickets} — ${team(opponent(state.fixture)).name} need ${state.target} to win.`;}else if(!isBatting&&(state.oppBalls>=12||state.oppRuns>=state.target)){state.matchDone=true;finishFixture();}renderMatch();animateBall(runs,out);}
window.quickOver=()=>{for(let i=0;i<6&&state.screen==='match'&&!state.matchDone;i++)playBall()};
function finishFixture(){let won=state.runs>state.oppRuns,draw=state.runs===state.oppRuns;state.points[state.userId]+=won?2:draw?1:0;state.points[opponent(state.fixture)]+=won?0:draw?1:2;state.results.push({id:state.userId,opp:opponent(state.fixture),won,score:`${state.runs}/${state.wickets}`,against:`${state.oppRuns}/${state.oppWickets}`});state.message=won?'Victory! Two points in the bag.':draw?'A tie — one point each.':'The rival takes the points. Next match.';state.lastBall=`${won?'🏆':draw?'🤝':'🏟️'} &nbsp;<strong>${state.message}</strong> Final score ${state.runs}/${state.wickets} to ${state.oppRuns}/${state.oppWickets}.`;}
window.continueAfterMatch=()=>{state.fixture++;if(state.fixture>=3){state.screen='result';renderResult()}else{state.screen='lobby';renderLobby()}};
function renderResult(){let sorted=[...TEAMS].sort((a,b)=>state.points[b.id]-state.points[a.id]),champ=sorted[0];screen.innerHTML=`<div style="max-width:780px;margin:6vh auto;text-align:center"><div style="font-size:60px">🏆</div><div class="eyebrow">Season 2026 · final table</div><h1 class="heading">${champ.id===state.userId?'Champions.':'Season complete.'}</h1><p class="subhead">${champ.id===state.userId?'You built a team, backed your instincts and brought the trophy home.':`${champ.name} take the title this season. Build again and come back stronger.`}</p><section class="panel" style="text-align:left;margin:28px 0"><div class="panel-head"><h3 class="panel-title">Final standings</h3><span class="mini-label">3 MATCHES · 2 PTS FOR A WIN</span></div>${standingsHTML()}</section><div style="display:flex;justify-content:center;gap:10px"><button class="btn" onclick="newSeason()">Play another season ↗</button></div></div>`}
window.newSeason=()=>{state=freshState();render()};window.confirmLeave=()=>{if(confirm('Leave this match and return to your franchise?')){state.screen='lobby';renderLobby()}};

// A self-contained Three.js night ground; the rest of the game remains playable if a CDN is unavailable.
async function initScene(){const canvas=$('#pitch');if(!canvas)return;try{const THREE=await import('https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js');if(!$('#pitch'))return;let renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(canvas.clientWidth,canvas.clientHeight,false);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;let scene=new THREE.Scene();scene.background=new THREE.Color('#0a2524');scene.fog=new THREE.Fog('#0a2524',22,48);let camera=new THREE.PerspectiveCamera(42,canvas.clientWidth/canvas.clientHeight,.1,100);camera.position.set(0,12,20);camera.lookAt(0,0,0);scene.add(new THREE.HemisphereLight('#b8e4d5','#172523',2));let key=new THREE.DirectionalLight('#fff1cf',3.2);key.position.set(-7,12,4);key.castShadow=true;scene.add(key);
