// Simple stands and crowd lights form a readable, low-poly arena bowl.
for(let i=0;i<200;i++){let a=Math.random()*Math.PI*2,r=18.5+Math.random()*1.4,y=.2+Math.random()*3;let dot=new THREE.Mesh(new THREE.BoxGeometry(.12,.12,.12),mat(['#ef8254','#d4e66a','#d7e4dc','#55a69a'][i%4]));dot.position.set(Math.cos(a)*r,y,Math.sin(a)*r);scene.add(dot)}
let pitch=new THREE.Mesh(new THREE.BoxGeometry(3.2,.1,8.5),mat('#b9a67c'));pitch.position.y=.05;pitch.receiveShadow=true;scene.add(pitch);let strip=new THREE.Mesh(new THREE.BoxGeometry(1.3,.04,8),mat('#cfba8d'));strip.position.y=.12;scene.add(strip);for(let z of [-3.1,-2.8,-2.5,2.5,2.8,3.1]){let st=new THREE.Mesh(new THREE.CylinderGeometry(.055,.055,.8,8),mat('#e9e1c4'));st.position.set(0,.52,z);scene.add(st)}
const playerMat=(color)=>mat(color,.55);function cricketer(x,z,color,bat){let g=new THREE.Group(),body=new THREE.Mesh(new THREE.CapsuleGeometry(.32,.68,4,8),playerMat(color));body.position.y=1.05;body.castShadow=true;g.add(body);let head=new THREE.Mesh(new THREE.SphereGeometry(.23,12,9),mat('#bd805a'));head.position.y=1.72;g.add(head);let helmet=new THREE.Mesh(new THREE.SphereGeometry(.25,12,7,0,Math.PI*2,0,Math.PI*.56),mat('#17292a'));helmet.position.y=1.85;g.add(helmet);for(let s of [-1,1]){let leg=new THREE.Mesh(new THREE.CylinderGeometry(.10,.12,.7,7),mat('#d7dfd2'));leg.position.set(s*.16,.39,0);g.add(leg)}if(bat){let batmesh=new THREE.Mesh(new THREE.BoxGeometry(.09,.1,1.12),mat('#d5b576'));batmesh.position.set(.56,.9,-.35);batmesh.rotation.x=-.2;batmesh.rotation.z=-.22;g.add(batmesh)}g.position.set(x,0,z);scene.add(g);return g}let striker=cricketer(.68,2.9,'#d7f16b',true),bowler=cricketer(-.35,-3.15,'#ed795b',false);striker.rotation.y=Math.PI;let nonstriker=cricketer(1.1,-2.55,'#d7f16b',false);nonstriker.scale.setScalar(.9);let ball=new THREE.Mesh(new THREE.SphereGeometry(.16,12,10),mat('#f77b55',.3));ball.position.set(-.3,1.1,-2.4);scene.add(ball);
for(let x of [-10.3,10.3]){let pole=new THREE.Mesh(new THREE.CylinderGeometry(.1,.14,8,8),mat('#90ada3'));pole.position.set(x,4,0);scene.add(pole);let lamp=new THREE.PointLight('#f8ebbc',45,19);lamp.position.set(x,8.1,0);scene.add(lamp);let head=new THREE.Mesh(new THREE.BoxGeometry(1.3,.25,.5),mat('#e4e6cc'));head.position.set(x,8.1,0);scene.add(head)}
const resize=()=>{let w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()};let ro=new ResizeObserver(resize);ro.observe(canvas);let frame=0;const loop=()=>{if(!document.body.contains(canvas)){ro.disconnect();renderer.dispose();return}frame++;striker.rotation.y=Math.PI+Math.sin(frame*.006)*.035;renderer.render(scene,camera);requestAnimationFrame(loop)};scene3d={ball,renderer};loop();}catch(e){fallbackPitch(canvas)}}
