function animateBall(runs,out){if(scene3d?.ball){let b=scene3d.ball,start=performance.now(),from=new THREEVector(-.3,1.1,-2.4),end=out?new THREEVector(-.5,.4,-1):runs>=4?new THREEVector(2,1.9,-8):new THREEVector(.3,.4,1.8);function tick(now){let t=Math.min((now-start)/650,1);b.position.set(from.x+(end.x-from.x)*t,from.y+(end.y-from.y)*t+Math.sin(t*Math.PI)*(runs>=4?3:.6),from.z+(end.z-from.z)*t);if(t<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)}}
